  ant: 'Nega uso de substâncias. Ano de vestibular.',
  ef: 'Exame físico normal no momento.',
  sv: 'FC 84 bpm · PA 112/70 mmHg',
  ex: 'ECG normal. TSH normal. Hemograma normal.',
